/*
 * "Pular para…" (tecla #): o número da postagem. O core não tem
 * a janela; a linha do tempo só deixa arrastar. (Não há opção por
 * data: a API do Flarum não acha um post pela data.)
 */

import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import Stream from 'flarum/common/utils/Stream';
import { t } from '../../utils/settings';
export default class JumpToPostModal extends FormModal {
  number = Stream('');
  className() {
    return 'CanelaJumpModal Modal--small';
  }
  title() {
    return t('gaps.jump.title');
  }
  content() {
    const count = this.attrs.stream?.count?.() || 0;
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form-group CanelaJumpModal-number"
    }, m("label", {
      for: "canela-jump-number"
    }, t('gaps.jump.post_label')), m("div", {
      className: "CanelaJumpModal-row"
    }, m("input", {
      id: "canela-jump-number",
      className: "FormControl",
      type: "number",
      min: "1",
      max: count || undefined,
      bidi: this.number,
      placeholder: "#"
    }), m("span", {
      className: "CanelaJumpModal-of"
    }, t('gaps.jump.of', {
      count
    })))), m("div", {
      className: "Form-group"
    }, m(Button, {
      className: "Button Button--primary Button--block",
      type: "submit"
    }, t('gaps.jump.submit'))));
  }
  onsubmit(event) {
    event.preventDefault();
    const stream = this.attrs.stream;
    const number = parseInt(this.number(), 10);
    this.hide();
    if (number > 0) stream.goToNumber(number);
  }
}
flarum.reg.add('ramon-canela', 'forum/gaps/topic/JumpToPostModal', JumpToPostModal);